-- CPF R6 V106 persistent data-quality provider schema
-- vendor=oracle; logicalDatabase=cpfDB
BEGIN EXECUTE IMMEDIATE 'ALTER TABLE CPF_DATA_QUALITY_RULE ADD (PARAMETERS_PAYLOAD BLOB)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE != -1430 THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'ALTER TABLE CPF_DATA_QUALITY_QUARANTINE ADD (VIOLATION_PAYLOAD BLOB)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE != -1430 THEN RAISE; END IF; END;
/
BEGIN
  EXECUTE IMMEDIATE q'[CREATE TABLE CPF_DATA_QUALITY_OPERATION (
    OPERATION_ID VARCHAR2(160 CHAR) NOT NULL,
    OPERATION_TYPE VARCHAR2(64 CHAR) NOT NULL,
    QUARANTINE_ID VARCHAR2(64 CHAR) NOT NULL,
    COMMAND_FINGERPRINT CHAR(64 CHAR) NOT NULL,
    RESULT_PAYLOAD BLOB NOT NULL,
    ACTOR_ID VARCHAR2(64 CHAR) NOT NULL,
    ACTION_REASON VARCHAR2(1000 CHAR) NOT NULL,
    CREATED_AT TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT PK_CPF_DQ_OPERATION PRIMARY KEY (OPERATION_ID),
    CONSTRAINT FK_CPF_DQ_OPERATION_QUARANTINE FOREIGN KEY (QUARANTINE_ID) REFERENCES CPF_DATA_QUALITY_QUARANTINE(QUARANTINE_ID),
    CONSTRAINT CK_CPF_DQ_OPERATION_HASH CHECK (LENGTH(COMMAND_FINGERPRINT)=64))]';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -955 THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE INDEX IX_CPF_DQ_OPERATION_TARGET ON CPF_DATA_QUALITY_OPERATION (QUARANTINE_ID, OPERATION_TYPE, CREATED_AT)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE != -955 THEN RAISE; END IF; END;
/
